from collections import deque


class RegexError(ValueError):
    pass


def _validate_alphabet(alphabet: str):
    if not alphabet or len(alphabet) > 8:
        raise RegexError("alphabet must contain 1 to 8 characters")
    if len(set(alphabet)) != len(alphabet):
        raise RegexError("alphabet contains duplicate characters")


class _Parser:
    def __init__(self, s: str):
        self.s = s
        self.n = len(s)
        self.pos = 0

    def parse(self):
        node = self._alt()
        if self.pos != self.n:
            raise RegexError("unbalanced parentheses")
        return node

    def _peek(self):
        return self.s[self.pos] if self.pos < self.n else ""

    def _alt(self):
        parts = [self._cat()]
        while self.pos < self.n and self.s[self.pos] == "|":
            self.pos += 1
            parts.append(self._cat())
        if len(parts) == 1:
            return parts[0]
        return _Union(parts)

    def _cat(self):
        parts = []
        while self.pos < self.n and self.s[self.pos] not in "|)":
            c = self.s[self.pos]
            if c in "*+?":
                raise RegexError("quantifier without preceding element")
            atom = self._atom()
            if self.pos < self.n and self.s[self.pos] in "*+?":
                if self.s[self.pos] in "*+?":
                    q = self.s[self.pos]
                    self.pos += 1
                    if self.pos < self.n and self.s[self.pos] in "*+?":
                        raise RegexError("quantifier applied to quantifier")
                    atom = _Quant(q, atom)
            parts.append(atom)
        if not parts:
            return _EPS
        if len(parts) == 1:
            return parts[0]
        return _Concat(parts)

    def _atom(self):
        c = self.s[self.pos]
        if c == "(":
            self.pos += 1
            g = self._alt()
            if self.pos >= self.n or self.s[self.pos] != ")":
                raise RegexError("unbalanced parentheses")
            self.pos += 1
            return _Group(g)
        if c == "[":
            return self._charset()
        if c == ".":
            self.pos += 1
            return _Dot()
        if c == "\\":
            self.pos += 1
            if self.pos >= self.n:
                raise RegexError("backslash at end")
            ch = self.s[self.pos]
            self.pos += 1
            return _Literal(ch)
        self.pos += 1
        return _Literal(c)

    def _charset(self):
        self.pos += 1
        neg = False
        if self.pos < self.n and self.s[self.pos] == "^":
            neg = True
            self.pos += 1

        pos_chars = set()
        ranges = []
        item_count = 0

        while True:
            if self.pos >= self.n:
                raise RegexError("unterminated character class")
            c = self.s[self.pos]
            if c == "]":
                if item_count == 0:
                    raise RegexError("empty character class")
                self.pos += 1
                return _CharSet(neg, pos_chars, ranges)

            escaped = False
            if c == "\\":
                if self.pos + 1 >= self.n:
                    raise RegexError("backslash at end")
                first = self.s[self.pos + 1]
                escaped = True
                self.pos += 2
            else:
                first = c
                self.pos += 1

            if escaped or first == "-":
                pos_chars.add(first)
                item_count += 1
                continue

            if self.pos < self.n and self.s[self.pos] == "-":
                if self.pos + 1 >= self.n:
                    raise RegexError("unterminated character class")
                if self.s[self.pos + 1] == "]":
                    pos_chars.add(first)
                    item_count += 1
                    continue

                self.pos += 1
                if self.pos < self.n and self.s[self.pos] == "\\":
                    if self.pos + 1 >= self.n:
                        raise RegexError("backslash at end")
                    last = self.s[self.pos + 1]
                    self.pos += 2
                else:
                    last = self.s[self.pos]
                    self.pos += 1

                if ord(first) > ord(last):
                    raise RegexError("bad character range")
                ranges.append((first, last))
                item_count += 1
            else:
                pos_chars.add(first)
                item_count += 1


class _Node:
    __slots__ = ()


class _EpsilonNode(_Node):
    __slots__ = ()

    def __repr__(self):
        return "eps"


class _Literal(_Node):
    __slots__ = ("ch",)

    def __init__(self, ch):
        self.ch = ch

    def __repr__(self):
        return f"lit({self.ch!r})"


class _Dot(_Node):
    __slots__ = ()

    def __repr__(self):
        return "dot"


class _CharSet(_Node):
    __slots__ = ("neg", "chars", "ranges")

    def __init__(self, neg, chars, ranges):
        self.neg = neg
        self.chars = chars
        self.ranges = ranges

    def __repr__(self):
        return f"class(neg={self.neg}, chars={self.chars}, ranges={self.ranges})"


class _Concat(_Node):
    __slots__ = ("parts",)

    def __init__(self, parts):
        self.parts = tuple(parts)


class _Union(_Node):
    __slots__ = ("parts",)

    def __init__(self, parts):
        self.parts = tuple(parts)


class _Group(_Node):
    __slots__ = ("node",)

    def __init__(self, node):
        self.node = node


class _Quant(_Node):
    __slots__ = ("kind", "node")

    def __init__(self, kind, node):
        self.kind = kind
        self.node = node


_EPS = _EpsilonNode()


class _NFA:
    __slots__ = ("eps", "trans", "accept", "start", "final")

    def __init__(self):
        self.eps = []
        self.trans = []
        self.accept = []
        self.start = self._new_state()
        self.final = self._new_state()
        self.eps[self.start].append(self.final)

    def _new_state(self):
        self.eps.append([])
        self.trans.append([])
        self.accept.append(False)
        return len(self.eps) - 1

    def _copy(self, sub):
        mp = {}
        for i, es in enumerate(sub.eps):
            mp[i] = self._new_state()
        for i, es in enumerate(sub.eps):
            for j in es:
                self.eps[mp[i]].append(mp[j])
        for i, ts in enumerate(sub.trans):
            for ch, j in ts:
                self.trans[mp[i]].append((ch, mp[j]))
        self.accept[mp[sub.final]] = True
        return mp[sub.start], mp[sub.final]

    def build(self, alphabet: str):
        self.eps = [[] for _ in range(len(self.eps))]
        self.trans = [[] for _ in range(len(self.trans))]
        self.accept = [False] * len(self.accept)
        self.start = self._new_state()
        self.final = self._new_state()
        self.eps[self.start].append(self.final)

    def make_literal(self, node):
        a = self._new_state()
        b = self._new_state()
        if node.ch in self.alphabet_set:
            self.trans[a].append((node.ch, b))
        return a, b

    def make_dot(self):
        a = self._new_state()
        b = self._new_state()
        for ch in self.alphabet:
            self.trans[a].append((ch, b))
        return a, b

    def make_charset(self, node):
        a = self._new_state()
        b = self._new_state()
        for ch in self.alphabet:
            ok = ch in node.chars or any(lo <= ch <= hi for lo, hi in node.ranges)
            if node.neg:
                ok = not ok
            if ok:
                self.trans[a].append((ch, b))
        return a, b

    def make_concat(self, node):
        first = None
        last = None
        for part in node.parts:
            a, b = self.make(part)
            if first is None:
                first = a
            if last is not None:
                self.eps[last].append(a)
            last = b
        return first, last

    def make_union(self, node):
        a = self._new_state()
        b = self._new_state()
        for part in node.parts:
            ca, cb = self.make(part)
            self.eps[a].append(ca)
            self.eps[cb].append(b)
        return a, b

    def make_group(self, node):
        return self.make(node.node)

    def make_quant(self, node):
        sa, sb = self.make(node.node)
        if node.kind == "*":
            a = self._new_state()
            b = self._new_state()
            self.eps[a].append(sa)
            self.eps[a].append(b)
            self.eps[sb].append(sa)
            self.eps[sb].append(b)
            return a, b
        if node.kind == "+":
            a = self._new_state()
            b = self._new_state()
            self.eps[a].append(sa)
            self.eps[sb].append(sa)
            self.eps[sb].append(b)
            return a, b
        if node.kind == "?":
            a = self._new_state()
            b = self._new_state()
            self.eps[a].append(sa)
            self.eps[a].append(b)
            self.eps[sb].append(b)
            return a, b
        raise RegexError("bad quantifier")

    def make(self, node):
        if isinstance(node, _EpsilonNode):
            return self._epsilon_edge()
        if isinstance(node, _Literal):
            return self.make_literal(node)
        if isinstance(node, _Dot):
            return self.make_dot()
        if isinstance(node, _CharSet):
            return self.make_charset(node)
        if isinstance(node, _Concat):
            return self.make_concat(node)
        if isinstance(node, _Union):
            return self.make_union(node)
        if isinstance(node, _Group):
            return self.make_group(node)
        if isinstance(node, _Quant):
            return self.make_quant(node)
        raise RegexError("unknown AST node")

    def _epsilon_edge(self):
        a = self._new_state()
        b = self._new_state()
        self.eps[a].append(b)
        return a, b

    def build_from_ast(self, ast, alphabet):
        self.alphabet = alphabet
        self.alphabet_set = set(alphabet)
        sa, sb = self.make(ast)
        self.eps[self.start].append(sa)
        self.eps[sb].append(self.final)
        self.accept[self.final] = True


def _parse(pattern: str, alphabet: str):
    _validate_alphabet(alphabet)
    if "\\" in pattern and pattern.endswith("\\"):
        raise RegexError("backslash at end")
    return _Parser(pattern).parse()


def _epsilon_closures(nfa: _NFA):
    n = len(nfa.eps)
    eps_mask = [0] * n
    for i, es in enumerate(nfa.eps):
        m = 0
        for j in es:
            m |= 1 << j
        eps_mask[i] = m

    closure = [0] * n
    for i in range(n):
        mask = 1 << i
        stack = [i]
        while stack:
            v = stack.pop()
            targets = eps_mask[v] & ~mask
            while targets:
                lsb = targets & -targets
                j = lsb.bit_length() - 1
                targets -= lsb
                stack.append(j)
                mask |= lsb
        closure[i] = mask
    return closure


def _make_block_tables(n: int, move_state, closure, alphabet):
    m = len(alphabet)
    block_size = 8
    nb = (n + block_size - 1) // block_size

    closure_table = []
    for bi in range(nb):
        tbl = [0] * (1 << block_size)
        base = bi * block_size
        for mask in range(1, 1 << block_size):
            lsb = mask & -mask
            idx = lsb.bit_length() - 1
            prev = mask ^ lsb
            st = base + idx
            if st < n:
                tbl[mask] = tbl[prev] | closure[st]
            else:
                tbl[mask] = tbl[prev]
        closure_table.append(tbl)

    move_tables = []
    for ci in range(m):
        tables = []
        for bi in range(nb):
            tbl = [0] * (1 << block_size)
            base = bi * block_size
            for mask in range(1, 1 << block_size):
                lsb = mask & -mask
                idx = lsb.bit_length() - 1
                prev = mask ^ lsb
                st = base + idx
                if st < n:
                    tbl[mask] = tbl[prev] | move_state[st][ci]
                else:
                    tbl[mask] = tbl[prev]
            tables.append(tbl)
        move_tables.append(tables)

    return closure_table, move_tables, nb


def _subset_transition(smask, ci, move_tables, closure_table, nb):
    target = 0
    b = smask
    idx = 0
    tbls = move_tables[ci]
    while b and idx < nb:
        byte = b & 0xff
        if byte:
            target |= tbls[idx][byte]
        b >>= 8
        idx += 1

    res = 0
    b = target
    idx = 0
    while b and idx < nb:
        byte = b & 0xff
        if byte:
            res |= closure_table[idx][byte]
        b >>= 8
        idx += 1
    return res


def _build_subset_dfa(pattern: str, alphabet: str):
    ast = _parse(pattern, alphabet)

    nfa = _NFA()
    nfa.build_from_ast(ast, alphabet)
    n = len(nfa.eps)

    closure = _epsilon_closures(nfa)

    m = len(alphabet)
    char_index = {ch: i for i, ch in enumerate(alphabet)}
    move_state = [[0] * m for _ in range(n)]
    for i, trans in enumerate(nfa.trans):
        for ch, j in trans:
            move_state[i][char_index[ch]] |= 1 << j

    accept_mask = 0
    for i, ok in enumerate(nfa.accept):
        if ok:
            accept_mask |= 1 << i

    closure_table, move_tables, nb = _make_block_tables(n, move_state, closure, alphabet)

    start = closure[0]
    state_masks = [start]
    state_id = {start: 0}
    trans = [[-1] * m]
    accept = [bool(start & accept_mask)]
    dead = -1

    head = 0
    while head < len(state_masks):
        sid = head
        smask = state_masks[head]
        head += 1

        for ci in range(m):
            target = _subset_transition(smask, ci, move_tables, closure_table, nb)
            if target == 0:
                if dead == -1:
                    dead = len(state_masks)
                    state_masks.append(0)
                    state_id[0] = dead
                    trans.append(list(range(m)) if False else [-1] * m)
                    for j in range(m):
                        trans[dead][j] = dead
                    accept.append(False)
                t = dead
            else:
                t = state_id.get(target)
                if t is None:
                    t = len(state_masks)
                    state_id[target] = t
                    state_masks.append(target)
                    trans.append([-1] * m)
                    accept.append(bool(target & accept_mask))
            trans[sid][ci] = t

    if dead == -1:
        has_missing = any(t == -1 for row in trans for t in row)
        if has_missing:
            dead = len(state_masks)
            state_masks.append(0)
            state_id[0] = dead
            trans.append(list(range(m)) if False else [-1] * m)
            for j in range(m):
                trans[dead][j] = dead
            accept.append(False)
            for row in trans:
                for ci in range(m):
                    if row[ci] == -1:
                        row[ci] = dead

    return trans, accept


def _minimize_dfa(trans, accept):
    n = len(trans)
    if n <= 1:
        return [0], accept, [0]

    m = len(trans[0])
    alphabet_count = m

    pred = [[[] for _ in range(n)] for _ in range(m)]
    for s in range(n):
        for c in range(m):
            pred[c][trans[s][c]].append(s)

    blocks = []
    block_id = [-1] * n

    acc_block = [i for i, ok in enumerate(accept) if ok]
    nonacc_block = [i for i, ok in enumerate(accept) if not ok]
    if acc_block:
        blocks.append(acc_block)
        bid = len(blocks) - 1
        for s in acc_block:
            block_id[s] = bid
    if nonacc_block:
        blocks.append(nonacc_block)
        bid = len(blocks) - 1
        for s in nonacc_block:
            block_id[s] = bid

    if len(blocks) == 1:
        return list(range(n)), accept, block_id

    q = deque()
    for b in range(len(blocks)):
        for c in range(m):
            q.append((b, c))

    mark = [0] * n
    token = 0

    while q:
        b, c = q.popleft()
        if b >= len(blocks):
            continue
        splitter = blocks[b]
        if not splitter:
            continue

        token += 1
        touched = []
        touched_flag = [False] * len(blocks)

        for s in splitter:
            for p in pred[c][s]:
                if p < n:
                    mark[p] = token
                    pb = block_id[p]
                    if not touched_flag[pb]:
                        touched_flag[pb] = True
                        touched.append(pb)

        for pb in touched:
            if pb >= len(blocks):
                continue
            old = blocks[pb]
            if not old:
                continue

            part_in = []
            part_out = []
            for s in old:
                if mark[s] == token:
                    part_in.append(s)
                else:
                    part_out.append(s)

            if not part_in or not part_out:
                continue

            if len(part_in) <= len(part_out):
                kept = part_out
                moved = part_in
            else:
                kept = part_in
                moved = part_out

            blocks[pb] = kept
            nb = len(blocks)
            blocks.append(moved)
            for s in moved:
                block_id[s] = nb

            for s in kept:
                block_id[s] = pb

            for c2 in range(m):
                q.append((pb, c2))
                q.append((nb, c2))

    b = len(blocks)
    new_trans = []
    new_accept = []
    for bid, bl in enumerate(blocks):
        rep = bl[0]
        new_accept.append(accept[rep])
        row = [block_id[trans[rep][c]] for c in range(m)]
        new_trans.append(row)

    new_start = block_id[0]
    return new_trans, new_accept, [new_start]


def _canonical_dfa_equal(trans1, acc1, trans2, acc2):
    if len(trans1) != len(trans2) or len(trans1[0]) != len(trans2[0]):
        return False
    m = len(trans1[0])

    map1to2 = {0: 0}
    visited1 = {0}
    visited2 = {0}
    q = deque([(0, 0)])

    if acc1[0] != acc2[0]:
        return False

    while q:
        a, b = q.popleft()
        for c in range(m):
            ta = trans1[a][c]
            tb = trans2[b][c]
            if ta in map1to2:
                if map1to2[ta] != tb:
                    return False
            else:
                if tb in visited2:
                    return False
                map1to2[ta] = tb
                visited1.add(ta)
                visited2.add(tb)
                if acc1[ta] != acc2[tb]:
                    return False
                q.append((ta, tb))

    return len(visited1) == len(trans1) and len(visited2) == len(trans2)


def _build_min_dfa(pattern: str, alphabet: str):
    trans, accept = _build_subset_dfa(pattern, alphabet)
    if not trans:
        return [[0]], [False], 0
    trans, accept, start_list = _minimize_dfa(trans, accept)
    start = start_list[0] if start_list else 0
    return trans, accept, start


def min_dfa_size(pattern: str, alphabet: str) -> int:
    trans, accept, _ = _build_min_dfa(pattern, alphabet)
    return len(trans)


def distinguish(p1: str, p2: str, alphabet: str) -> str | None:
    _validate_alphabet(alphabet)
    t1, a1, s1 = _build_min_dfa(p1, alphabet)
    t2, a2, s2 = _build_min_dfa(p2, alphabet)

    if _canonical_dfa_equal(t1, a1, t2, a2):
        return None

    m = len(alphabet)
    n1 = len(t1)
    n2 = len(t2)
    start = s1 * n2 + s2

    if a1[s1] != a2[s2]:
        return ""

    if n1 * n2 <= 2_000_000:
        size = n1 * n2
        parent = [-1] * size
        parent[start] = -2
        q = deque([start])
        while q:
            u = q.popleft()
            i = u // n2
            j = u % n2
            for c, ch in enumerate(alphabet):
                ni = t1[i][c]
                nj = t2[j][c]
                v = ni * n2 + nj
                if parent[v] == -1:
                    if a1[ni] != a2[nj]:
                        parts = []
                        cur = v
                        while parent[cur] != -2:
                            par = parent[cur]
                            parts.append(alphabet[par % m])
                            cur = par // m
                        return "".join(reversed(parts))
                    parent[v] = (u << 3) | c
                    q.append(v)
        return None

    parent = {start: (-1, None)}
    q = deque([(s1, s2, "")])
    visited = {start}
    while q:
        i, j, path = q.popleft()
        for ch in alphabet:
            ni = t1[i][alphabet.index(ch)] if False else t1[i][list(alphabet).index(ch)]
            nj = t2[j][alphabet.index(ch)] if False else t2[j][list(alphabet).index(ch)]
            if a1[ni] != a2[nj]:
                return path + ch
            v = ni * n2 + nj
            if v not in visited:
                visited.add(v)
                parent[v] = (i * n2 + j, ch)
                q.append((ni, nj, path + ch))
    return None
